public class TraceEmitter {
    public static String constructed() {
        return new DmlException().getStackTraceString();
    }
    public static String thrown() {
        try { throw new IllegalArgumentException('probe failure'); }
        catch (Exception fault) { return fault.getStackTraceString(); }
    }
}

